import java.io.BufferedInputStream

private const val MOD = 1_000_000_007L

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var len = 0
    private var ptr = 0

    private fun readByte(): Int {
        if (ptr >= len) {
            len = input.read(buffer)
            ptr = 0
            if (len <= 0) return -1
        }
        return buffer[ptr++].toInt()
    }

    fun nextInt(): Int {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)
        var result = 0
        while (c > 32) {
            result = result * 10 + (c - '0'.code)
            c = readByte()
        }
        return result
    }
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextInt()
    val k = fs.nextInt()

    val inv = LongArray(n.coerceAtLeast(2))
    val g = LongArray(n)
    inv[1] = 1L
    g[0] = 1L

    var window = 1L
    var sum = 1L

    for (m in 1 until n) {
        if (m > 1) {
            inv[m] = (MOD - (MOD / m * inv[(MOD % m).toInt()]) % MOD) % MOD
        }

        g[m] = window * inv[m] % MOD
        sum += g[m]
        if (sum >= MOD) sum -= MOD

        window += g[m]
        if (window >= MOD) window -= MOD

        val removeIndex = m - k
        if (removeIndex >= 0) {
            window -= g[removeIndex]
            if (window < 0) window += MOD
        }
    }

    var factorialNMinusOne = 1L
    for (i in 2 until n) {
        factorialNMinusOne = factorialNMinusOne * i % MOD
    }

    val successful = factorialNMinusOne * sum % MOD
    val factorialN = factorialNMinusOne * n % MOD
    val answer = (factorialN - successful + MOD) % MOD

    print(answer)
}

